                        {Math.round(hour.pop * 100)}%
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
            <ScrollBar orientation="horizontal" />
          </ScrollArea>
        </CardContent>
      )}
    </Card>
  );
}
