import { DailyForecast } from './DailyForecast';
import { WeatherHistory } from './WeatherHistory';
import type { WeatherLocationData, WeatherHistoryEntry, UnitSystem } from './types';
import { getLocationDisplayName } from './types';

interface WeatherDetailProps {
  /** Selected location data */
  location: WeatherLocationData;
  /** History entries (loaded separately) */
  history: WeatherHistoryEntry[];
  /** Current unit system */
  units: UnitSystem;
}

export function WeatherDetail({ location, history, units }: WeatherDetailProps) {
  const { current_report: report } = location;
  const displayName = getLocationDisplayName(
    location.latitude,
    location.longitude,
    report
  );

  return (
    <ScrollArea className="h-full">
