        {report.current && (
          <CurrentConditions
            current={report.current}
            timezoneOffset={report.timezone_offset}
            units={units}
          />
        )}

        {/* Hourly Forecast (collapsible) */}
        {report.hourly && report.hourly.length > 0 && (
          <HourlyForecast
            hourly={report.hourly}
