              </Button>

              {showAdvanced && (
                <div className="grid grid-cols-3 gap-4 p-3 border rounded-lg bg-muted/50">
                  <div className="space-y-2">
                    <Label className="text-xs">Cloud Cover (%)</Label>
                    <Input
